#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}




# ──────────────────────────────────────────────────────────────────────────
# STAGES: grava a chave da API do Portal da Transparência (catálogo D01) onde o ETL a lê: secret TRANSPARENCIA_API_KEY do GitHub (agenda em
# produção) e, se você quiser, um arquivo local fora do repositório (permissão 600) para rodar o ETL no Mac. Antes de guardar, testa a
# chave com `civico-etl transparencia.ping`. A chave é lida oculta, vai para o gh por stdin e NUNCA é impressa, nem em argv.
# O cadastro é pessoal (gov.br + e-mail): este assistente não o faz por você.
# Uso: etl/deploy/transparencia-key.sh
# Teste sem efeito colateral: SKIP_GH=1 SKIP_PING=1 TRANSPARENCIA_KEY_FILE=/tmp/x/key etl/deploy/transparencia-key.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
PY="$ROOT/etl/.venv/bin/python"
export GH_REPO="${GH_REPO:-AlexandreCamerini/replica}"
ENV_FILE="/nonexistent/.env"   # nada é gravado nem sugerido de .env
KEY_FILE="${TRANSPARENCIA_KEY_FILE:-$HOME/.config/civico-etl/transparencia-key}"
KEY=""
STORED_GH=""; STORED_LOCAL=""

# ping_with KEY: roda o ping do ETL com a chave só no ambiente deste comando. Saída do ETL descartada (mensagens têm a chave? não, mas
# a política é não imprimir nada que passe por ela). Devolve o exit do ping: 0 ok, 1 recusada, 2 sem chave, 3 inconclusivo.
ping_with() {
  [[ -n "${SKIP_PING:-}" ]] && return 0
  ( cd "$ROOT/etl" && TRANSPARENCIA_API_KEY="$1" TRANSPARENCIA_KEY_FILE=/nonexistent "$PY" -m civico_etl.cli transparencia.ping ) >/dev/null 2>&1
}

banner "Chave da API do Portal da Transparência"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos"
[[ -x "$PY" ]] || { warn "falta etl/.venv (cd etl && python3 -m venv .venv && .venv/bin/pip install -e .)"; exit 1; }
if [[ -z "${SKIP_GH:-}" ]]; then
  command -v gh >/dev/null || { warn "falta o gh: brew install gh"; exit 1; }
  gh auth status >/dev/null 2>&1 || { warn "gh sem login: rode gh auth login e repita"; exit 1; }
  say "Secret irá para o repositório $GH_REPO."
else
  note "SKIP_GH: o secret do GitHub não será gravado"
fi
say "Arquivo local (opcional): $KEY_FILE"
pause "Enter para seguir"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Pedir a chave (você, no navegador)"
say "A chave é pessoal: o cadastro usa o seu e-mail e a API só a envia para esse e-mail."
step "Abra a página de cadastro e informe o e-mail que vai usar:"
open_url "https://portaldatransparencia.gov.br/api-de-dados/cadastrar-email"
step "Abra o e-mail que a CGU enviar e copie a chave (uma linha, sem espaços)."
note "Limite de requisições: por minuto, maior de 00h às 06h. O ETL já espaça as chamadas."
pause "Já copiou a chave? Enter para colar"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Colar e testar a chave"
while :; do
  ask_secret KEY "Cole a chave (entrada oculta):"
  KEY="${KEY//[[:space:]]/}"
  [[ -n "$KEY" ]] || { warn "chave vazia; parei aqui"; exit 1; }   # também fim da entrada: sem isso o laço não para
  if [[ ! "$KEY" =~ ^[A-Za-z0-9._-]{16,128}$ ]]; then warn "formato estranho (esperava 16 a 128 letras, números, ponto, hífen ou sublinhado); cole de novo"; continue; fi
  say "Testando na API (transparencia.ping)..."
  set +e; ping_with "$KEY"; rc=$?; set -e
  case "$rc" in
    0) printf '  %s✓%s a API aceitou a chave\n' "$GREEN" "$RESET"; break ;;
    1) warn "a API recusou a chave (401/403). Confira se copiou inteira e se confirmou o e-mail."
       confirm "Tentar colar de novo?" || { warn "nada foi gravado"; exit 1; } ;;
    *) warn "teste inconclusivo (rede, limite ou API fora do ar; código $rc)."
       if confirm "Guardar a chave mesmo assim e testar depois?"; then break; fi
       confirm "Tentar colar de novo?" || { warn "nada foi gravado"; exit 1; } ;;
  esac
done

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Secret do GitHub"
if [[ -n "${SKIP_GH:-}" ]]; then
  note "SKIP_GH: pulado"
elif confirm "Gravar como secret TRANSPARENCIA_API_KEY em $GH_REPO (a agenda de produção passa a ler emendas e CGU)?"; then
  # stdin, nunca --body: a chave não aparece em argv nem no histórico
  if printf '%s' "$KEY" | gh secret set TRANSPARENCIA_API_KEY --repo "$GH_REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("TRANSPARENCIA_API_KEY"); STORED_GH=1
    printf '  %s✓ set%s GitHub secret TRANSPARENCIA_API_KEY\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("GitHub secret TRANSPARENCIA_API_KEY (rode de novo ou: gh secret set TRANSPARENCIA_API_KEY --repo $GH_REPO)")
    warn "o gh não gravou o secret"
  fi
else
  SKIPPED+=("GitHub secret TRANSPARENCIA_API_KEY (você recusou)")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Arquivo local e teste final"
if confirm "Gravar também em $KEY_FILE (permissão 600, fora do repositório) para rodar o ETL no Mac?"; then
  case "$KEY_FILE" in "$ROOT"/*) warn "o caminho está dentro do repositório; escolha outro (TRANSPARENCIA_KEY_FILE)"; exit 1 ;; esac
  ( umask 077; mkdir -p "$(dirname "$KEY_FILE")"; printf '%s\n' "$KEY" >"$KEY_FILE" )
  chmod 600 "$KEY_FILE"
  STORED_LOCAL=1
  printf '  %s✓ wrote%s %s (modo 600)\n' "$GREEN" "$RESET" "$KEY_FILE"
fi
unset KEY
if [[ -n "$STORED_LOCAL" ]]; then
  say "Teste final, lendo do arquivo (como o ETL lê):"
  if ( cd "$ROOT/etl" && env -u TRANSPARENCIA_API_KEY TRANSPARENCIA_KEY_FILE="$KEY_FILE" "$PY" -m civico_etl.cli transparencia.ping ) 2>&1 | sed 's/^/    /'; then :; fi
else
  note "sem arquivo local: o ping local usa a variável TRANSPARENCIA_API_KEY ou o arquivo acima"
fi
[[ -n "$STORED_GH" ]] && note "Produção: o próximo run da agenda passa a carregar emendas e CGU. Para forçar agora: gh workflow run etl.yml -f only=transparencia.emendas"

finish
